BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role text NOT NULL DEFAULT 'agent' CHECK(role IN ('owner','manager','agent')),is_active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),owner_id uuid REFERENCES users(id),name text NOT NULL,email text,phone text,source text,notes text,tags text[] NOT NULL DEFAULT '{}',custom_fields jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_contacts_company ON contacts(company_id);
CREATE TABLE IF NOT EXISTS pipelines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),name text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pipeline_id uuid NOT NULL REFERENCES pipelines(id) ON DELETE CASCADE,name text NOT NULL,position integer NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','won','lost')));
CREATE TABLE IF NOT EXISTS opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),pipeline_id uuid NOT NULL REFERENCES pipelines(id),stage_id uuid NOT NULL REFERENCES stages(id),contact_id uuid NOT NULL REFERENCES contacts(id),owner_id uuid REFERENCES users(id),title text NOT NULL,value numeric(14,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','won','lost','abandoned')),lost_reason text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),contact_id uuid NOT NULL REFERENCES contacts(id),assignee_id uuid REFERENCES users(id),channel text NOT NULL DEFAULT 'internal',external_id text,status text NOT NULL DEFAULT 'open',unread_count integer NOT NULL DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id uuid REFERENCES users(id),direction text NOT NULL CHECK(direction IN ('inbound','outbound','internal')),body text NOT NULL,external_id text,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),contact_id uuid REFERENCES contacts(id),owner_id uuid REFERENCES users(id),title text NOT NULL,due_at timestamptz,completed boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),contact_id uuid REFERENCES contacts(id),owner_id uuid REFERENCES users(id),title text NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'scheduled',created_at timestamptz DEFAULT now(),CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,company_id uuid REFERENCES companies(id),user_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,details jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());
COMMIT;